export const TARGET_NAMES = ["claude", "cursor", "codex", "amp"];
export const AGENT_TYPES = ["claude-code", "cursor", "codex", "amp"];
const AGENT_BY_TARGET = {
    claude: "claude-code",
    cursor: "cursor",
    codex: "codex",
    amp: "amp",
};
const TARGET_BY_AGENT = {
    "claude-code": "claude",
    cursor: "cursor",
    codex: "codex",
    amp: "amp",
};
export const AGENT_LABELS = {
    "claude-code": "Claude Code",
    cursor: "Cursor",
    codex: "Codex",
    amp: "Amp",
};
export function agentForTarget(target) {
    return AGENT_BY_TARGET[target];
}
export function targetForAgent(agent) {
    return TARGET_BY_AGENT[agent];
}
export function isAgentType(value) {
    return AGENT_TYPES.includes(value);
}
export function isTargetName(value) {
    return TARGET_NAMES.includes(value);
}
